// Original generative soundtrack. All sounds synthesized locally; no samples or network.
export class Soundscape {
 constructor(){this.ctx=null;this.enabled=false;this.timer=null;this.step=0;this.tension=0;}
 async toggle(){if(!this.ctx)this.init();this.enabled=!this.enabled;if(this.enabled){await this.ctx.resume();this.master.gain.cancelScheduledValues(this.ctx.currentTime);this.master.gain.setTargetAtTime(.42,this.ctx.currentTime,.3);this.next=this.ctx.currentTime+.08;this.timer=setInterval(()=>this.schedule(),80);}else{this.master.gain.setTargetAtTime(0,this.ctx.currentTime,.15);clearInterval(this.timer);}return this.enabled;}
 init(){const c=this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=c.createGain();this.master.gain.value=0;const compressor=c.createDynamicsCompressor();compressor.threshold.value=-20;compressor.ratio.value=5;this.master.connect(compressor);compressor.connect(c.destination);const delay=c.createDelay(2),feedback=c.createGain(),wet=c.createGain();delay.delayTime.value=.45;feedback.gain.value=.32;wet.gain.value=.22;delay.connect(feedback);feedback.connect(delay);delay.connect(wet);wet.connect(this.master);this.delay=delay;const len=c.sampleRate*2,imp=c.createBuffer(2,len,c.sampleRate);for(let ch=0;ch<2;ch++){const data=imp.getChannelData(ch);for(let i=0;i<len;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/len,3);}this.reverb=c.createConvolver();this.reverb.buffer=imp;const rg=c.createGain();rg.gain.value=.32;this.reverb.connect(rg);rg.connect(this.master);this.noise=c.createBuffer(1,c.sampleRate,c.sampleRate);const nd=this.noise.getChannelData(0);for(let i=0;i<nd.length;i++)nd[i]=Math.random()*2-1;document.addEventListener('visibilitychange',()=>{if(!this.enabled)return;if(document.hidden)c.suspend();else{c.resume();this.next=c.currentTime+.1;}});}
 note(freq,t,len,amp=.06,type='sine',pan=0){const c=this.ctx,o=c.createOscillator(),g=c.createGain(),p=c.createStereoPanner();o.type=type;o.frequency.value=freq;p.pan.value=pan;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(amp,t+.018);g.gain.exponentialRampToValueAtTime(.0001,t+len);o.connect(g);g.connect(p);p.connect(this.master);p.connect(this.delay);p.connect(this.reverb);o.start(t);o.stop(t+len+.02);}
 drum(t,kick){const c=this.ctx,g=c.createGain();if(kick){const o=c.createOscillator();o.frequency.setValueAtTime(120,t);o.frequency.exponentialRampToValueAtTime(40,t+.2);g.gain.setValueAtTime(.2,t);g.gain.exponentialRampToValueAtTime(.0001,t+.35);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+.4);}else{const n=c.createBufferSource(),f=c.createBiquadFilter();n.buffer=this.noise;f.type='highpass';f.frequency.value=6500;g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.0001,t+.065);n.connect(f);f.connect(g);g.connect(this.master);n.start(t);n.stop(t+.08);}}
 schedule(){const c=this.ctx;if(!this.enabled||c.state!=='running')return;if(this.next<c.currentTime)this.next=c.currentTime+.05;while(this.next<c.currentTime+.18){const t=this.next,s=this.step%32;const chords=[[130.81,164.81,196,246.94],[110,130.81,164.81,196],[87.31,110,130.81,164.81],[98,123.47,146.83,196]];let chord=chords[Math.floor(this.step/32)%4];if(s%16===0){chord.forEach((f,i)=>{this.note(f,t+i*.04,4,.025,'sine',(i-1.5)*.35);this.note(f*1.003,t+i*.04,3.8,.012,'triangle',(1.5-i)*.35);});}if(s%8===0)this.drum(t,true);if(s%4===2)this.drum(t,false);if(s%2===0){const seq=[0,2,1,3,2,0,3,1];this.note(chord[seq[(s/2)%8]]*2,t,.5,.025,'sine',Math.sin(s)*.55);}if(this.tension>.5&&s%4===0)this.note(chord[0]*4,t,.12,.012,'triangle');this.step++;this.next+=.225;}}
 effect(kind,p=1){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime;if(kind==='pick'){this.note(p===1?659.25:493.88,t,.18,.09,'sine',p===1?-.4:.4);}if(kind==='link'){[1,1.5,2].forEach((m,i)=>this.note((p===1?261.63:220)*m,t+i*.06,.45,.07,'triangle',p===1?-.3:.3));}if(kind==='reset'){[261.63,329.63,392,523.25].forEach((f,i)=>this.note(f,t+i*.08,.7,.065));}if(kind==='collapse'){[196,185,146.83,130.81,98,65.41].forEach((f,i)=>this.note(f,t+i*.12,1.8,.1,'triangle'));this.drum(t+.15,true);}}
}
